import type { Request } from "./request";

export interface RetryOptions {
  attempts?: number;
}

export function withRetry(request: Request, options: RetryOptions = {}): Promise<unknown> {
  const maxAttempts = options.attempts ?? 3;
  const maxBackoffMs = 30000;
  return attemptRequest(request, maxAttempts, 0, maxBackoffMs);
}
